import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.DTdEDYjJ.js";const b=JSON.parse('{"title":"贾维斯模式","description":"","frontmatter":{},"headers":[],"relativePath":"guide/jarvis.md","filePath":"guide/jarvis.md"}'),i={name:"guide/jarvis.md"};function s(d,t,l,h,p,n){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="贾维斯模式" tabindex="-1">贾维斯模式 <a class="header-anchor" href="#贾维斯模式" aria-label="Permalink to &quot;贾维斯模式&quot;">​</a></h1><p>贾维斯模式让你日常面对一个主 Bot：它按职责向已有执行 Bot 派单，读回真实结果后汇总。执行 Bot 仍保留自己的身份、连接、模型、Harness、记忆与文件空间。</p><p>该模式是显示与协作入口。进入模式不会替任何 Bot 开启工具、安装执行器或补齐凭据。</p><h2 id="_1-准备主脑和执行-bot" tabindex="-1">1. 准备主脑和执行 Bot <a class="header-anchor" href="#_1-准备主脑和执行-bot" aria-label="Permalink to &quot;1. 准备主脑和执行 Bot&quot;">​</a></h2><ol><li>为主 Bot 配置可用的 API 模型，在主 Bot 设置中显式开启工具。</li><li>创建或选择已有执行 Bot，写清职责，例如研究、核查与写作。</li><li>分别配置执行 Bot 的连接、模型和现有 Harness。可以共用连接，也可以各用不同服务。</li><li>文字任务无需给执行 Bot 开工具；需要它浏览网页时，再显式启用其工具。</li><li>绑定 CLI/ACP 的 Bot 还需本机已经安装并登录对应执行器。</li></ol><table tabindex="0"><thead><tr><th>接收者</th><th>任务能力</th><th>不包含</th></tr></thead><tbody><tr><td>API 文字 Bot</td><td>分析、写作、文字交付</td><td>屏幕操作、再次派单</td></tr><tr><td>API 浏览器 Bot</td><td>本 Bot 屏幕的六项浏览器工具</td><td>文件工具、组织管理、递归派单</td></tr><tr><td>本机 CLI/ACP Bot</td><td>已有执行器及工作目录</td><td>API 浏览器任务模式</td></tr></tbody></table><p>CLI 或未启用工具的主脑只能对话与规划，不能把计划表述为已经派单。连接与健康检查见<a href="/openbot/guide/models.html">模型与连接</a>、<a href="/openbot/guide/harness.html">Harness</a>。</p><h2 id="_2-开启并交办" tabindex="-1">2. 开启并交办 <a class="header-anchor" href="#_2-开启并交办" aria-label="Permalink to &quot;2. 开启并交办&quot;">​</a></h2><p>点击主 Bot 聊天头部“贾维斯模式”，或在“展开工作”中开启同名开关。侧栏聚焦主 Bot，执行 Bot 在后台保留，原有工作继续存在。</p><p>先验证一次文字协作：</p><blockquote><p>让研究 Bot 列出这个方案需要核查的三项假设，让写作 Bot 整理一页提纲；等实际结果返回后，告诉我哪些是结论、哪些仍待核查。</p></blockquote><p>需要网页核查时明确指定浏览器工作：</p><blockquote><p>让研究 Bot 在自己的浏览器中核查 <a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a> 的标题和主要内容，不修改页面；读回实际结果后给我简报。</p></blockquote><p>每次派单继续审批，页面修改也继续逐次审批。省略浏览器模式的 API 派单始终为文字任务，不会因接收者已开工具而自动升级。</p><h2 id="_3-看懂运行反馈" tabindex="-1">3. 看懂运行反馈 <a class="header-anchor" href="#_3-看懂运行反馈" aria-label="Permalink to &quot;3. 看懂运行反馈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>反馈</th><th>对应事实</th></tr></thead><tbody><tr><td>梳理</td><td>主脑当前请求正在处理任务</td></tr><tr><td>分配或排队</td><td>已有真实派单调用，或任务正在等待</td></tr><tr><td>执行</td><td>至少一项实际工作仍在进行</td></tr><tr><td>待批或暂停</td><td>对应 Bot 等待授权或控制权恢复</td></tr><tr><td>汇总</td><td>当前父轮子任务已终结，且主脑已实际读回结果</td></tr></tbody></table><p>最多显示三个执行 Bot 头像，其余收为数量。一个 Bot 等待授权而另一个仍工作时，两者保留各自状态；失败、取消和部分完成不会显示成全部成功。</p><p>“显示执行进度”可以隐藏简短反馈，系统“减少动态效果”保留静态状态。动画和终态图标不能代替任务结果、页面核查或持久记录。</p><h2 id="_4-展开任务与关系图" tabindex="-1">4. 展开任务与关系图 <a class="header-anchor" href="#_4-展开任务与关系图" aria-label="Permalink to &quot;4. 展开任务与关系图&quot;">​</a></h2><p>在“展开工作与执行 Bot”查看任务、待批项、结果和关系图。头像间的箭头来自实际委派记录；点击 Bot 或箭头查看关联任务。</p><p>执行 Bot 隐藏时，其审批仍显示真实身份，任务也能按真实任务 ID 停止。查看执行 Bot 完整会话会明确退出模式；普通退出会恢复仍存在的原会话。</p><p>切换显示模式不取消后台工作。结果沿既有路径保存到接收 Bot 的会话、文件与记忆，再由主脑读回；宿主保存结果文件不代表执行 Bot 获得文件工具。</p><h2 id="_5-配置、权限与动作预算" tabindex="-1">5. 配置、权限与动作预算 <a class="header-anchor" href="#_5-配置、权限与动作预算" aria-label="Permalink to &quot;5. 配置、权限与动作预算&quot;">​</a></h2><p>排队任务保存其执行配置指纹。排队期间若模型、连接、Harness 或工具权限变化，任务拒绝执行；运行中的模型请求与原生输入前也重新核对权限。</p><p>每轮使用开始时固定的配置，不静默改用其他连接或 Harness。没有模型、审批被拒、权限缺失或任务未完成时，应如实报告，不自动重派。</p><p>本机父轮的有限动作额度在派单前共享并全额预占。取消、入队失败或未用完不返还这份分配；预占也不代表动作已经执行。无法安全分配页面条件时会拒绝浏览器委派。</p><p>跨机器父任务目前不能携带次数规则或页面完成条件委派。遇到拒绝时先核对原任务与页面，不能删除约束后当作同一任务继续。</p><h2 id="_6-停止与恢复" tabindex="-1">6. 停止与恢复 <a class="header-anchor" href="#_6-停止与恢复" aria-label="Permalink to &quot;6. 停止与恢复&quot;">​</a></h2><p>停止主脑当前轮次只请求取消该轮子任务，独立任务继续。单项任务也可从任务列表停止，不依赖当前选中的 Bot。</p><p>取消不撤销已经发生的网页或执行器操作。结果待核查时先看页面与记录；等待超时应保留真实状态，不重复派单。</p><p>重启后未完成任务标为中断，不重跑执行器；结果回写失败只补保存。Node 断线后需重连、看新画面并显式交还，详见<a href="/openbot/guide/computer-use.html">浏览器 Computer Use</a>。</p><h2 id="开发者本地验证" tabindex="-1">开发者本地验证 <a class="header-anchor" href="#开发者本地验证" aria-label="Permalink to &quot;开发者本地验证&quot;">​</a></h2><p>在源码根目录运行以下受控 Electron 套件，分别检查文字协作和执行 Bot 浏览器链路。它们使用独立数据及本地模型替身，不调用真实模型：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:jarvis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:worker-computer-use</span></span></code></pre></div><p>源码与最终包的验证需分别记录，具体方式见<a href="/openbot/development/contributing.html">参与开发</a>。当前没有递归组织、无人值守调度或完整 L3/L4 长期验收。</p><p>下一步可阅读<a href="/openbot/concepts/architecture.html">架构</a>、<a href="/openbot/deployment/self-host.html">自建 Linux Node</a>与<a href="/openbot/development/changelog.html">变更记录</a>。</p>`,36)])])}const u=a(i,[["render",s]]);export{b as __pageData,u as default};
